// historyArchive makes a temp archive and returns its path, so a command test
// never touches a real Garmin home.
func historyArchive(t *testing.T) (string, *store.Store) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "data.db")
	db, err := store.Open(path)
	if err != nil {
		t.Fatalf("open archive: %v", err)
	}
	if err := db.EnsureGarminSeriesState(); err != nil {
		t.Fatalf("ensure series state: %v", err)
	}
	t.Cleanup(func() { _ = db.Close() })
	return path, db
}

func runHistory(t *testing.T, flags *rootFlags, args ...string) (string, string, error) {
	t.Helper()
	cmd := newGarminHistoryCmd(flags)
	var out, errBuf bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(&errBuf)
	cmd.SetArgs(args)
	cmd.SilenceUsage = true
	cmd.SilenceErrors = true
	err := cmd.ExecuteContext(context.Background())
	return out.String(), errBuf.String(), err
}

// --days and --backfill are gone, and gone means gone: an alias that quietly
// did something else would leave the old muscle memory pointing at new
// behaviour (N131 decision D12).
func TestHistory_DeletedDepthFlagsAreUnknownFlags(t *testing.T) {
	for _, arg := range []string{"--days=3", "--backfill", "--empty-window-ceiling=5"} {
		_, _, err := runHistory(t, &rootFlags{}, arg)
		if err == nil {
			t.Fatalf("%s was accepted; it must be an unknown flag", arg)
		}
		if !strings.Contains(err.Error(), "unknown flag") {
			t.Fatalf("%s failed with %v, want an unknown-flag error", arg, err)
		}
	}
}

func TestHistory_SinceTakesAllOrADateAndSaysSoWhenItIsNeither(t *testing.T) {
	for _, good := range []string{"", "all", "ALL", "2026-06-01"} {
		depth, err := garminParseDepth(good)
		if err != nil {
			t.Fatalf("--since %q was rejected: %v", good, err)
		}
		switch {
		case good == "" && depth.mode != depthStored:
			t.Fatal("an absent --since must keep the stored depth")
		case strings.EqualFold(good, "all") && depth.mode != depthAll:
			t.Fatalf("--since all parsed as %v", depth.mode)
		case good == "2026-06-01" && depth.day.String() != "2026-06-01":
			t.Fatalf("--since 2026-06-01 parsed as %v", depth.day)
		}
	}
	for _, bad := range []string{"yesterday", "30", "2026-13-01", "june"} {
		if _, err := garminParseDepth(bad); err == nil {
			t.Fatalf("--since %q was accepted", bad)
		} else if !strings.Contains(err.Error(), "all") || !strings.Contains(err.Error(), "YYYY-MM-DD") {
			t.Fatalf("--since %q failed with %q, which does not name the two forms it accepts", bad, err)
		}
	}
}

// The mechanism flags still work — an escape hatch is worth having — but a
// caller reading --help is offered one decision, not nine.
func TestHistory_OnlyDepthAndTheTwoReportsAreVisibleInHelp(t *testing.T) {
	cmd := newGarminHistoryCmd(&rootFlags{})
	help := cmd.UsageString()
	for _, visible := range []string{"--since", "--status"} {
		if !strings.Contains(help, visible) {
			t.Fatalf("%s is missing from --help:\n%s", visible, help)
		}
	}
	// --strict is advertised (N131 D21); the rest stay hidden.
	if !strings.Contains(help, "--strict") {
		t.Fatalf("--strict is a caller-facing choice and must appear in --help:\n%s", help)
	}
	if flag := cmd.Flags().Lookup("strict"); flag == nil || flag.Hidden {
		t.Fatalf("--strict is missing or still hidden: %#v", flag)
	}
	for _, hidden := range []string{"--series", "--delay", "--max-pages", "--max-dependents", "--page-size", "--max-consecutive-failures", "--db"} {
		if strings.Contains(help, hidden) {
			t.Fatalf("%s is a mechanism flag and must not appear in --help:\n%s", hidden, help)
		}
		if cmd.Flags().Lookup(strings.TrimPrefix(hidden, "--")) == nil {
			t.Fatalf("%s was deleted rather than hidden; it is the escape hatch", hidden)
		}
	}
	for _, gone := range []string{"--days", "--backfill", "--empty-window-ceiling"} {
		if strings.Contains(help, gone) {
			t.Fatalf("%s is still offered in --help:\n%s", gone, help)
		}
	}
}

// A cap of "how many rows to fetch" is implementation detail leaking into a
// user's choice, so the default is no cap at all.
func TestHistory_DependentCapDefaultsToNoCap(t *testing.T) {
	cmd := newGarminHistoryCmd(&rootFlags{})
	if got := cmd.Flags().Lookup("max-dependents").DefValue; got != "0" {
		t.Fatalf("--max-dependents defaults to %q, want 0 (no cap)", got)
	}
}

func TestHistory_StatusReportsEachSeriesWithoutMakingARequest(t *testing.T) {
	path, db := historyArchive(t)
	if err := db.SaveGarminSeriesState(store.GarminSeriesState{
		Series: "steps", EarliestDay: "2020-07-06", LastCompleteDay: "2026-09-07",
	}); err != nil {
		t.Fatalf("seed state: %v", err)
	}
	seedSignalDays(t, db, "2026-09-05", "2026-09-06")

	out, _, err := runHistory(t, &rootFlags{}, "--status", "--db", path, "--series", "steps,daily_hr")
	if err != nil {
		t.Fatalf("--status failed: %v", err)
	}
	for _, want := range []string{"SERIES", "FILLED FROM", "COMPLETE THROUGH", "OUTSTANDING", "steps", "2020-07-06", "2026-09-07", "daily_hr"} {
		if !strings.Contains(out, want) {
			t.Fatalf("--status output is missing %q:\n%s", want, out)
		}
	}

	jsonOut, _, err := runHistory(t, &rootFlags{asJSON: true}, "--status", "--db", path, "--series", "steps")
	if err != nil {
		t.Fatalf("--status --json failed: %v", err)
	}
	var probe struct {
		Series []garminSeriesPlan `json:"series"`
	}
	if err := json.Unmarshal([]byte(jsonOut), &probe); err != nil {
		t.Fatalf("--status --json is not JSON (%v): %s", err, jsonOut)
	}
	if len(probe.Series) != 1 || probe.Series[0].Series != "steps" || probe.Series[0].LastComplete != "2026-09-07" {
		t.Fatalf("--status --json = %+v", probe.Series)
	}
}

// --dry-run reads the archive and reports what a real run would cost. It has
// no client to make a request with, which is why "no traffic" is a property of
// the code path rather than a promise about it.
func TestHistory_DryRunIsStateAwareAndCostsNothing(t *testing.T) {
	path, db := historyArchive(t)
	seedSignalDays(t, db, "2026-09-01", "2026-09-04", "2026-09-05")

	// --dry-run is a root persistent flag, so the test sets it the way the
	// root command would rather than passing it to the subcommand.
	out, notes, err := runHistory(t, &rootFlags{dryRun: true}, "--since", "all", "--db", path, "--series", "sleep_detail")
	if err != nil {
		t.Fatalf("--dry-run failed: %v", err)
	}
	if !strings.Contains(out, "sleep_detail") || !strings.Contains(out, "2026-09-01") {
		t.Fatalf("--dry-run did not report the per-day plan from state:\n%s", out)
	}
	if !strings.Contains(notes, "About 3 requests") {
		t.Fatalf("--dry-run estimate = %q, want the three signal days it read from the archive", notes)
	}
	// The old --dry-run printed "variable" for anything state-dependent.
	if strings.Contains(out, "variable") && !strings.Contains(out, "activities") {
		t.Fatalf("--dry-run still reports a state-dependent series as variable:\n%s", out)
	}
}

// historyOffline points a `history` run at a local server that fails the test
// if a request ever arrives, and at a scratch home and config so nothing reads
// the machine's real Garmin home. A run planned to make no request is then
// self-checking rather than promised.
func historyOffline(t *testing.T) {
	t.Helper()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		t.Errorf("history made a request to %s; this test must make none", r.URL.Path)
		w.WriteHeader(http.StatusInternalServerError)
	}))
	t.Cleanup(srv.Close)
	home := t.TempDir()
	t.Setenv("GARMIN_HOME", home)
	t.Setenv("GARMIN_CONFIG", filepath.Join(home, "config.toml"))
	t.Setenv("GARMIN_BASE_URL", srv.URL)
}

// A machine caller gets the same closing document from `history` that the
// generated `sync` prints: one JSON object on stdout carrying the six summary
// numbers, with the JSONL event stream on stderr. Without it stdout is empty
// and the only way to learn what a run did is to parse the event log — which
// is what the Agent Mode contract ("--json — one JSON document on stdout, sync
// progress events go to stderr") already tells a caller not to have to do.
func TestHistory_MachineModeEndsWithOneSummaryDocumentOnStdout(t *testing.T) {
	historyOffline(t)
	path, _ := historyArchive(t)

	// An empty archive gives a per-day series no signal day, so this run
	// walks one series and asks for nothing.
	out, events, err := runHistory(t, &rootFlags{asJSON: true}, "--db", path, "--series", "sleep_detail")
	if err != nil {
		t.Fatalf("history --json failed: %v\nstderr:\n%s", err, events)
	}

	trimmed := strings.TrimSpace(out)
	if strings.Contains(trimmed, `"event"`) {
		t.Fatalf("an event reached stdout; the stream belongs on stderr:\n%s", out)
	}
	var summary map[string]any
	if err := json.Unmarshal([]byte(trimmed), &summary); err != nil {
		t.Fatalf("stdout is not one JSON document (%v):\n%q", err, out)
	}
	want := []string{"total_records", "resources", "success", "warned", "errored", "duration_ms"}
	if len(summary) != len(want) {
		t.Fatalf("the closing document carries %d keys, want the six `sync` prints: %v", len(summary), summary)
	}
	for _, key := range want {
		if _, ok := summary[key]; !ok {
			t.Fatalf("the closing document is missing %q: %v", key, summary)
		}
	}
	if got, ok := summary["errored"].(float64); !ok || got != 0 {
		t.Fatalf("errored = %v, want 0: this run is supposed to ask for nothing", summary["errored"])
	}
	if got, ok := summary["resources"].(float64); !ok || got != 1 {
		t.Fatalf("resources = %v, want the one series the run walked", summary["resources"])
	}

	// The events still go to stderr, all of them, including the summary
	// event the document duplicates.
	if !strings.Contains(events, `"event":"sync_summary"`) || !strings.Contains(events, `"event":"sync_start"`) {
		t.Fatalf("the event stream is missing from stderr:\n%s", events)
	}

	// Human mode gains nothing: no document is appended to the report.
	humanOut, _, err := runHistory(t, &rootFlags{}, "--db", path, "--series", "sleep_detail")
	if err != nil {
		t.Fatalf("history failed: %v", err)
	}
	if strings.Contains(humanOut, "total_records") {
		t.Fatalf("human mode printed the machine document:\n%s", humanOut)
	}
}

// The estimate is arithmetic over named constants, not a vibe: change a byte
// constant or the latency and this test fails.
func TestEstimate_IsArithmeticOverTheMeasuredConstants(t *testing.T) {
	plans := []garminSeriesPlan{
		{Series: "sleep_detail", Outstanding: 100, Bytes: int64(100 * garminSeriesRowBytes["sleep_detail"]), Since: "2026-01-01"},
		{Series: "activity_detail", Outstanding: 50, Bytes: int64(50 * garminSeriesRowBytes["activity_detail"]), Since: "2025-06-01"},
		{Series: "activities", Outstanding: -1},
	}
	est := garminEstimateOf(plans, garminDepth{}, 300*time.Millisecond)
	if est.Requests != 150 {
		t.Fatalf("requests = %d, want 150 (the feed's unknown page count is left out, not guessed)", est.Requests)
	}
	if est.Since != "2025-06-01" {
		t.Fatalf("since = %q, want the oldest floor any outstanding series asked for", est.Since)
	}
	// 150 requests x (300 ms pacing + 130 ms observed latency) = 64.5 s.
	// Spelled out rather than recomputed from the constants: a test that
	// derives its expectation from the number it is checking checks nothing.
	if est.Minutes != 1.075 {
		t.Fatalf("minutes = %v, want 1.075 (150 requests at 300 ms pacing + 130 ms latency)", est.Minutes)
	}
	// 100 nights at 88 340 bytes plus 50 activity details at 3 327.
	if est.Megabytes != 9.00035 {
		t.Fatalf("megabytes = %v, want 9.00035 (88 KB a night is what makes a deep per-day fill worth warning about)", est.Megabytes)
	}
	if !strings.Contains(est.line(), "About 150 requests") || !strings.Contains(est.line(), "2025-06-01") {
		t.Fatalf("estimate line = %q", est.line())
	}
}

// Once a series holds enough rows, this archive's own average replaces the
// constant: an account whose nights are half the reference size should be told
// half the number.
func TestEstimate_UsesTheArchivesOwnAverageOnceItHasEnoughRows(t *testing.T) {
	_, db := historyArchive(t)
	planner := &garminPlanner{db: db, depth: sinceAll(), now: fixedClock("2026-09-08"), loc: time.UTC}
	if got := planner.rowBytes("sleep_detail"); got != garminSeriesRowBytes["sleep_detail"] {
		t.Fatalf("an empty series used %d bytes/row, want the measured constant %d", got, garminSeriesRowBytes["sleep_detail"])
	}

	padding := strings.Repeat("x", 400)
	for i := 0; i < garminMeasuredBytesMinRows; i++ {
		day := mustParseCivilDay("2026-01-01").addDays(i).String()
		if err := db.Upsert("sleep_detail", day, json.RawMessage(`{"calendarDate":"`+day+`","pad":"`+padding+`"}`)); err != nil {
			t.Fatalf("seed row: %v", err)
		}
	}
	got := planner.rowBytes("sleep_detail")
	if got >= garminSeriesRowBytes["sleep_detail"] {
		t.Fatalf("with %d stored rows the estimate still used the constant (%d bytes/row); it must use this archive's own average",
			garminMeasuredBytesMinRows, got)
	}
	if got < 400 {
		t.Fatalf("the measured average is %d bytes/row, which is smaller than the rows themselves", got)
	}
}

// --status answers "what do I still owe", and a caught-up series owes today's
// window and its refresh days on every run forever. Printing those as
// outstanding work reads as debt that never clears, and "variable" for the
// feed is implementation vocabulary in a column a household reader looks at.
func TestStatusCell_ACaughtUpSeriesReadsUpToDateAndTheFeedNamesItsUnknown(t *testing.T) {
	ceiling := mustParseCivilDay("2026-09-12")
	caughtUp := garminSeriesPlan{Series: "steps", LastComplete: "2026-09-12", Outstanding: 1}
	if got := garminStatusOutstandingCell(caughtUp, ceiling); got != "up to date" {
		t.Fatalf("a series complete through the newest complete day reads %q", got)
	}
	refreshing := garminSeriesPlan{Series: "daily_hr", LastComplete: "2026-09-12", Outstanding: 7}
	if got := garminStatusOutstandingCell(refreshing, ceiling); got != "up to date" {
		t.Fatalf("the 7-day refresh window reads %q, which is maintenance rather than debt", got)
	}
	behind := garminSeriesPlan{Series: "steps", LastComplete: "2026-06-30", Outstanding: 3}
	if got := garminStatusOutstandingCell(behind, ceiling); got != "3" {
		t.Fatalf("a series still filling reads %q, want the count it owes", got)
	}
	// The account's heart-rate zone configuration is replaced in place on
	// every run, so its permanent one request is maintenance too — until the
	// archive has no copy of it at all.
	doc := garminSeriesPlan{Series: "hr_zone_config", Kind: kindName(seriesSingleDocument), Rows: 1, Outstanding: 1}
	if got := garminStatusOutstandingCell(doc, ceiling); got != "up to date" {
		t.Fatalf("a stored single-document series reads %q", got)
	}
	empty := garminSeriesPlan{Series: "hr_zone_config", Kind: kindName(seriesSingleDocument), Rows: 0, Outstanding: 1}
	if got := garminStatusOutstandingCell(empty, ceiling); got != "1" {
		t.Fatalf("a single-document series with no row reads %q, want the request it owes", got)
	}
	feed := garminSeriesPlan{Series: "activities", Outstanding: -1}
	for what, got := range map[string]string{
		"--status":  garminStatusOutstandingCell(feed, ceiling),
		"--dry-run": garminOutstandingCell(feed.Outstanding),
	} {
		if got != "pages until the feed ends" {
			t.Fatalf("%s renders the feed's unknown count as %q", what, got)
		}
	}
	// A --dry-run cell is a request count, not a status: the footer adds
	// those numbers up, so they stay numbers.
	if got := garminOutstandingCell(7); got != "7" {
		t.Fatalf("--dry-run REQUESTS cell = %q, want the count the estimate sums", got)
	}
}

// The estimate's date is where the archive ENDS UP. It used to open "Fetching
// everything since <day>", which on a caught-up archive named a floor the run
// would not go near.
func TestEstimateLine_NamesTheCoverageItLeavesBehindAndCountsOneRequestSingular(t *testing.T) {
	one := garminWorkEstimate{Since: "2011-10-29", Requests: 1, Minutes: 0.007, Megabytes: 0.3}
	got := one.line()
	if !strings.Contains(got, "About 1 request,") || strings.Contains(got, "1 requests") {
		t.Fatalf("line = %q, want a singular request", got)
	}
	if strings.Contains(got, "about under a minute") {
		t.Fatalf("line = %q: the duration phrase carries its own hedge", got)
	}
	if !strings.Contains(got, "under a minute") || !strings.Contains(got, "archive covers 2011-10-29 to today") {
		t.Fatalf("line = %q, want the duration and the coverage it leaves behind", got)
	}
	if strings.Contains(got, "Fetching everything since") {
		t.Fatalf("line = %q: the date is the coverage, not the first day fetched", got)
	}
	many := garminWorkEstimate{Since: "2007-01-01", Requests: 9314, Minutes: 66.8, Megabytes: 239}
	if l := many.line(); !strings.Contains(l, "About 9314 requests") || !strings.Contains(l, "about 1.1 h") {
		t.Fatalf("line = %q, want the plural count and an hours phrase", l)
	}
	mid := garminWorkEstimate{Since: "2026-01-01", Requests: 300, Minutes: 2.15}
	if l := mid.line(); !strings.Contains(l, "about 2 min") {
		t.Fatalf("line = %q, want a minutes phrase", l)
	}
}
